class Solution {
public:
    double trimMean(vector<int>& arr) {
        int n = arr.size();
        int remove = n / 20;
        nth_element(arr.begin(), arr.begin() + remove, arr.end());
        nth_element(arr.begin() + remove, arr.begin() + n - remove - 1, arr.end());
        long long sum = 0;
        for (int i = remove; i < n - remove; ++i) {
            sum += arr[i];
        }
        return (double)sum / (n - 2 * remove);
    }
};
